CREATE OR REPLACE FUNCTION private.save_website_global_settings_before_fonts(content jsonb, expected_updated_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor uuid := private.current_user_id();
  current_updated_at timestamptz;
  navbar jsonb;
  brand jsonb;
  palette jsonb;
  type_settings jsonb;
  socials jsonb;
  item jsonb;
  logo_path text;
  favicon_path text;
  allowed_fonts constant text[] := array['Inter', 'Georgia', 'system-ui'];
  allowed_socials constant text[] := array['instagram', 'facebook', 'x', 'youtube', 'pinterest', 'linkedin'];
begin
  if actor is null or not private.is_admin() then
    raise exception 'Admin access required' using errcode = '42501';
  end if;
  if content is null or jsonb_typeof(content) is distinct from 'object' then
    raise exception 'Global settings must be an object' using errcode = '22023';
  end if;
  if not content ?& array['navbar_items','branding','colors','typography','social_links']
     or (select count(*) from jsonb_object_keys(content)) <> 5 then
    raise exception 'Global settings must contain every supported field and no extras' using errcode = '22023';
  end if;

  navbar := content -> 'navbar_items';
  brand := content -> 'branding';
  palette := content -> 'colors';
  type_settings := content -> 'typography';
  socials := content -> 'social_links';
  if jsonb_typeof(navbar) is distinct from 'array'
     or jsonb_typeof(brand) is distinct from 'object'
     or jsonb_typeof(palette) is distinct from 'object'
     or jsonb_typeof(type_settings) is distinct from 'object'
     or jsonb_typeof(socials) is distinct from 'array' then
    raise exception 'Global settings have an invalid structure' using errcode = '22023';
  end if;
  if jsonb_array_length(navbar) > 8 or jsonb_array_length(socials) > 6 then
    raise exception 'Global settings exceed their item limits' using errcode = '22023';
  end if;

  for item in select value from jsonb_array_elements(navbar) loop
    if jsonb_typeof(item) is distinct from 'object'
       or not item ?& array['id','label','path','enabled','sort_order']
       or (select count(*) from jsonb_object_keys(item)) <> 5 then
      raise exception 'Navbar item must contain exactly id, label, path, enabled, and sort_order' using errcode = '22023';
    end if;
    if jsonb_typeof(item -> 'id') is distinct from 'string'
       or jsonb_typeof(item -> 'label') is distinct from 'string'
       or jsonb_typeof(item -> 'path') is distinct from 'string'
       or jsonb_typeof(item -> 'enabled') is distinct from 'boolean'
       or jsonb_typeof(item -> 'sort_order') is distinct from 'number'
       or (item ->> 'sort_order') !~ '^[1-8]$' then
      raise exception 'Navbar item contains an invalid value type' using errcode = '22023';
    end if;
    if (item ->> 'id') !~ '^[a-z][a-z0-9_-]{0,31}$'
       or char_length(btrim(item ->> 'label')) not between 1 and 40
       or (item ->> 'path') !~ '^/(?:[a-z0-9][a-z0-9-]*(?:/[a-z0-9][a-z0-9-]*)*)?(?:\?[a-z0-9][a-z0-9%._=&-]*)?$'
       or (item ->> 'path') like '%..%'
       or (item ->> 'path') like '//%'
       or (item ->> 'sort_order')::integer not between 1 and 8 then
      raise exception 'Navbar item is invalid' using errcode = '22023';
    end if;
  end loop;
  if (select count(*) <> count(distinct value ->> 'id') or count(*) <> count(distinct (value ->> 'sort_order')::integer)
      from jsonb_array_elements(navbar)) then
    raise exception 'Navbar ids and ordering must be unique' using errcode = '22023';
  end if;

  if not brand ?& array['display_name','tagline','logo_path','logo_alt','logo_width','logo_height','favicon_path']
     or (select count(*) from jsonb_object_keys(brand)) <> 7 then
    raise exception 'Branding must contain every supported field and no extras' using errcode = '22023';
  end if;
  if jsonb_typeof(brand -> 'display_name') is distinct from 'string'
     or jsonb_typeof(brand -> 'tagline') is distinct from 'string'
     or jsonb_typeof(brand -> 'logo_path') not in ('string','null')
     or jsonb_typeof(brand -> 'logo_alt') not in ('string','null')
     or jsonb_typeof(brand -> 'logo_width') not in ('number','null')
     or jsonb_typeof(brand -> 'logo_height') not in ('number','null')
     or jsonb_typeof(brand -> 'favicon_path') not in ('string','null') then
    raise exception 'Branding contains an invalid value type' using errcode = '22023';
  end if;
  if char_length(btrim(brand ->> 'display_name')) not between 1 and 40
     or char_length(btrim(brand ->> 'tagline')) not between 1 and 100 then
    raise exception 'Brand text is invalid' using errcode = '22023';
  end if;
  logo_path := case when jsonb_typeof(brand -> 'logo_path') = 'string' then btrim(brand ->> 'logo_path') else null end;
  favicon_path := case when jsonb_typeof(brand -> 'favicon_path') = 'string' then btrim(brand ->> 'favicon_path') else null end;
  if (jsonb_typeof(brand -> 'logo_path') = 'string' and logo_path !~ '^branding/[0-9a-f]{64}\.(jpg|png|webp)$')
     or (jsonb_typeof(brand -> 'favicon_path') = 'string' and favicon_path !~ '^branding/[0-9a-f]{64}\.(jpg|png|webp)$') then
    raise exception 'Brand media path is invalid' using errcode = '22023';
  end if;
  if logo_path is null then
    if jsonb_typeof(brand -> 'logo_alt') is distinct from 'null'
       or jsonb_typeof(brand -> 'logo_width') is distinct from 'null'
       or jsonb_typeof(brand -> 'logo_height') is distinct from 'null' then
      raise exception 'Logo metadata requires a logo path' using errcode = '22023';
    end if;
  else
    if jsonb_typeof(brand -> 'logo_alt') is distinct from 'string'
       or jsonb_typeof(brand -> 'logo_width') is distinct from 'number'
       or jsonb_typeof(brand -> 'logo_height') is distinct from 'number'
       or (brand ->> 'logo_width') !~ '^[1-9][0-9]{0,4}$'
       or (brand ->> 'logo_height') !~ '^[1-9][0-9]{0,4}$' then
      raise exception 'Brand logo metadata has invalid types' using errcode = '22023';
    end if;
    if char_length(btrim(brand ->> 'logo_alt')) not between 1 and 160
       or (brand ->> 'logo_width')::integer not between 1 and 12000
       or (brand ->> 'logo_height')::integer not between 1 and 12000 then
      raise exception 'Brand logo metadata is invalid' using errcode = '22023';
    end if;
  end if;
  if (logo_path is not null and not exists (select 1 from storage.objects where bucket_id='percent-website-media' and name=logo_path))
     or (favicon_path is not null and not exists (select 1 from storage.objects where bucket_id='percent-website-media' and name=favicon_path)) then
    raise exception 'Brand media is unavailable' using errcode = '22023';
  end if;

  if not palette ?& array['background','surface','text','muted','accent','accent_hover','border','highlight']
     or (select count(*) from jsonb_object_keys(palette)) <> 8 then
    raise exception 'Colors must contain every supported token and no extras' using errcode = '22023';
  end if;
  if exists (select 1 from jsonb_each(palette) where jsonb_typeof(value) is distinct from 'string')
     or exists (select 1 from jsonb_each_text(palette) where value !~ '^#[0-9a-fA-F]{6}$') then
    raise exception 'Colors must be complete six-digit hex values' using errcode = '22023';
  end if;

  if not type_settings ?& array['display_family','heading_family','body_family','ui_family','heading_weight','body_weight','letter_spacing']
     or (select count(*) from jsonb_object_keys(type_settings)) <> 7 then
    raise exception 'Typography must contain every supported field and no extras' using errcode = '22023';
  end if;
  if jsonb_typeof(type_settings -> 'display_family') is distinct from 'string'
     or jsonb_typeof(type_settings -> 'heading_family') is distinct from 'string'
     or jsonb_typeof(type_settings -> 'body_family') is distinct from 'string'
     or jsonb_typeof(type_settings -> 'ui_family') is distinct from 'string'
     or jsonb_typeof(type_settings -> 'heading_weight') is distinct from 'number'
     or jsonb_typeof(type_settings -> 'body_weight') is distinct from 'number'
     or jsonb_typeof(type_settings -> 'letter_spacing') is distinct from 'number'
     or (type_settings ->> 'heading_weight') !~ '^(400|500|600|700|800)$'
     or (type_settings ->> 'body_weight') !~ '^(400|500|600|700)$'
     or (type_settings ->> 'letter_spacing') !~ '^-?[0-9]+(?:\.[0-9]+)?$' then
    raise exception 'Typography contains an invalid value type' using errcode = '22023';
  end if;
  if not (type_settings ->> 'display_family' = any(allowed_fonts))
     or not (type_settings ->> 'heading_family' = any(allowed_fonts))
     or not (type_settings ->> 'body_family' = any(allowed_fonts))
     or not (type_settings ->> 'ui_family' = any(allowed_fonts))
     or (type_settings ->> 'heading_weight')::integer not in (400,500,600,700,800)
     or (type_settings ->> 'body_weight')::integer not in (400,500,600,700)
     or (type_settings ->> 'letter_spacing')::numeric not between -0.05 and 0.30 then
    raise exception 'Typography setting is invalid' using errcode = '22023';
  end if;

  for item in select value from jsonb_array_elements(socials) loop
    if jsonb_typeof(item) is distinct from 'object'
       or not item ?& array['platform','url','enabled','sort_order']
       or (select count(*) from jsonb_object_keys(item)) <> 4 then
      raise exception 'Social link must contain exactly platform, url, enabled, and sort_order' using errcode = '22023';
    end if;
    if jsonb_typeof(item -> 'platform') is distinct from 'string'
       or jsonb_typeof(item -> 'url') is distinct from 'string'
       or jsonb_typeof(item -> 'enabled') is distinct from 'boolean'
       or jsonb_typeof(item -> 'sort_order') is distinct from 'number'
       or (item ->> 'sort_order') !~ '^[1-6]$' then
      raise exception 'Social link contains an invalid value type' using errcode = '22023';
    end if;
    if not (item ->> 'platform' = any(allowed_socials))
       or (item ->> 'url') !~* '^https://([a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}(?::[0-9]{1,5})?(?:/[^[:space:]]*)?$'
       or (item ->> 'sort_order')::integer not between 1 and 6 then
      raise exception 'Social link is invalid' using errcode = '22023';
    end if;
  end loop;
  if (select count(*) <> count(distinct value ->> 'platform') or count(*) <> count(distinct (value ->> 'sort_order')::integer)
      from jsonb_array_elements(socials)) then
    raise exception 'Social platforms and ordering must be unique' using errcode = '22023';
  end if;

  select updated_at into current_updated_at
  from public.website_settings where id='storefront' for update;
  if current_updated_at is distinct from expected_updated_at then
    raise exception 'Website content changed; refresh and retry' using errcode = 'PT409';
  end if;

  update public.website_settings set
    navbar_items = navbar,
    branding = brand,
    colors = palette,
    typography = type_settings,
    social_links = socials,
    updated_at = clock_timestamp()
  where id='storefront';

  return public.get_website_editor();
end;
$function$

CREATE OR REPLACE FUNCTION public.save_website_global_settings(content jsonb, expected_updated_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_type jsonb;
  v_legacy jsonb;
  v_key text;
  v_version timestamptz;
begin
  if private.current_user_id() is null or not private.is_admin() then
    raise exception 'Admin access required' using errcode='42501';
  end if;
  -- All font management and typography saves lock the same singleton first.
  -- This serializes reference changes against disable/delete/face removal.
  select updated_at into v_version from public.website_settings where id='storefront' for update;
  if not found or expected_updated_at is null or v_version is distinct from expected_updated_at then
    raise exception 'Website content changed; refresh and retry' using errcode='PT409';
  end if;
  v_type:=content->'typography';
  if jsonb_typeof(v_type) is distinct from 'object' then
    raise exception 'Typography must be an object' using errcode='22023';
  end if;
  v_legacy:=v_type;
  foreach v_key in array array['display_family','heading_family','body_family','ui_family'] loop
    if jsonb_typeof(v_type->v_key) is distinct from 'string'
      or not private.website_font_reference_valid(v_type->>v_key) then
      raise exception 'Typography references an unavailable font' using errcode='22023';
    end if;
    -- Existing strict global validation still validates every other field, key,
    -- weight and spacing value and performs its original PT409-protected save.
    v_legacy:=jsonb_set(v_legacy,array[v_key],'"Inter"'::jsonb);
  end loop;
  perform private.save_website_global_settings_before_fonts(jsonb_set(content,'{typography}',v_legacy),expected_updated_at);
  -- Same transaction and version: restore only the already validated families.
  update public.website_settings set typography=v_type where id='storefront';
  return public.get_website_editor();
end;
$function$

CREATE OR REPLACE FUNCTION public.delete_website_font_family(p_family_id uuid, p_expected_updated_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_version timestamptz;
  v_paths jsonb;
begin
  if private.current_user_id() is null or not private.is_admin() then
    raise exception 'Admin access required' using errcode='42501';
  end if;
  perform 1 from public.website_settings where id='storefront' for update;
  select updated_at into v_version from public.website_font_families where id=p_family_id for update;
  if not found or p_expected_updated_at is null or v_version is distinct from p_expected_updated_at then
    raise exception 'Font family changed; reload before deleting' using errcode='PT409';
  end if;
  if private.website_font_in_use(p_family_id) then
    raise exception 'This font is currently used by the storefront. Choose another font before deleting it.' using errcode='22023';
  end if;
  select coalesce(jsonb_agg(storage_path),'[]'::jsonb) into v_paths from public.website_font_faces where family_id=p_family_id;
  delete from public.website_font_families where id=p_family_id;
  -- The authorized Edge Function removes bytes through Storage API, not SQL.
  return jsonb_build_object('removed',true,'cleanup_paths',v_paths);
end;
$function$

CREATE OR REPLACE FUNCTION public.save_website_font_family(p_family_id uuid, p_family_name text, p_enabled boolean, p_license_confirmed boolean, p_faces jsonb, p_expected_updated_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_existing public.website_font_families%rowtype;
  v_face jsonb;
  v_name text;
  v_path text;
  v_live boolean;
begin
  if private.current_user_id() is null or not private.is_admin() then
    raise exception 'Admin access required' using errcode='42501';
  end if;
  perform 1 from public.website_settings where id='storefront' for update;
  if not found then raise exception 'Website settings unavailable' using errcode='22023'; end if;
  select * into v_existing from public.website_font_families where id=p_family_id for update;
  if (v_existing.id is null and p_expected_updated_at is not null)
    or (v_existing.id is not null and (p_expected_updated_at is null or v_existing.updated_at is distinct from p_expected_updated_at)) then
    raise exception 'Font family changed; reload before saving' using errcode='PT409';
  end if;
  v_name:=regexp_replace(btrim(p_family_name),'[[:space:]]+',' ','g');
  if p_family_id is null or p_enabled is null or p_license_confirmed is distinct from true
    or v_name is null or char_length(v_name) not between 1 and 80 or v_name ~ '[[:cntrl:]]' then
    raise exception 'Enter a valid family name and confirm webfont permission' using errcode='22023';
  end if;
  if jsonb_typeof(p_faces) is distinct from 'array' then
    raise exception 'Font faces must be an array' using errcode='22023';
  end if;
  if jsonb_array_length(p_faces) not between 1 and 18 then
    raise exception 'Provide between 1 and 18 font faces' using errcode='22023';
  end if;
  if exists (select 1 from public.website_font_families where normalized_name=lower(v_name) and id<>p_family_id) then
    raise exception 'A font family with this name already exists' using errcode='23505';
  end if;
  for v_face in select value from jsonb_array_elements(p_faces) loop
    if jsonb_typeof(v_face) is distinct from 'object' then
      raise exception 'Invalid font face' using errcode='22023';
    end if;
    if not v_face ?& array['weight','style','storage_path','mime_type','byte_size','sha256']
      or (select count(*) from jsonb_object_keys(v_face))<>6
      or jsonb_typeof(v_face->'weight') is distinct from 'number'
      or (v_face->>'weight') !~ '^[1-9]00$'
      or jsonb_typeof(v_face->'style') is distinct from 'string'
      or (v_face->>'style') not in ('normal','italic')
      or jsonb_typeof(v_face->'storage_path') is distinct from 'string'
      or jsonb_typeof(v_face->'mime_type') is distinct from 'string'
      or (v_face->>'mime_type')<>'font/woff2'
      or jsonb_typeof(v_face->'byte_size') is distinct from 'number'
      or (v_face->>'byte_size') !~ '^[0-9]{1,7}$'
      or jsonb_typeof(v_face->'sha256') is distinct from 'string'
      or (v_face->>'sha256') !~ '^[0-9a-f]{64}$' then
      raise exception 'Invalid weight, style or WOFF2 metadata' using errcode='22023';
    end if;
    if (v_face->>'byte_size')::integer not between 48 and 2097152 then
      raise exception 'Font must be non-empty and no larger than 2 MB' using errcode='22023';
    end if;
    v_path:='fonts/'||p_family_id::text||'/'||(v_face->>'weight')||'-'||(v_face->>'style')||'-'||(v_face->>'sha256')||'.woff2';
    if (v_face->>'storage_path')<>v_path or not exists (
      select 1 from storage.objects o where o.bucket_id='percent-website-media' and o.name=v_path
        and o.metadata->>'mimetype'='font/woff2'
        and (o.metadata->>'size')::bigint=(v_face->>'byte_size')::integer
    ) then
      raise exception 'Font storage asset is unavailable or invalid' using errcode='22023';
    end if;
  end loop;
  if (select count(*)<>count(distinct (value->>'weight',value->>'style')) from jsonb_array_elements(p_faces)) then
    raise exception 'Each weight and style must be unique' using errcode='22023';
  end if;
  v_live:=private.website_font_in_use(p_family_id);
  if v_live and (not p_enabled or exists (
    select 1 from public.website_font_faces x where x.family_id=p_family_id
      and not exists (select 1 from jsonb_array_elements(p_faces) f where
        (f->>'weight')::integer=x.weight and f->>'style'=x.style and f->>'storage_path'=x.storage_path)
  )) then
    raise exception 'This font is currently used by the storefront. Choose another font before disabling it or removing a face.' using errcode='22023';
  end if;
  insert into public.website_font_families(id,family_name,enabled,license_confirmed)
  values(p_family_id,v_name,p_enabled,true)
  on conflict(id) do update set family_name=excluded.family_name,enabled=excluded.enabled,updated_at=clock_timestamp();
  delete from public.website_font_faces x where x.family_id=p_family_id and not exists (
    select 1 from jsonb_array_elements(p_faces) f where (f->>'weight')::integer=x.weight and f->>'style'=x.style
  );
  insert into public.website_font_faces(family_id,weight,style,storage_path,mime_type,byte_size,sha256)
  select p_family_id,(value->>'weight')::smallint,value->>'style',value->>'storage_path',value->>'mime_type',(value->>'byte_size')::integer,value->>'sha256'
  from jsonb_array_elements(p_faces)
  on conflict(family_id,weight,style) do update set
    asset_id=case when website_font_faces.storage_path=excluded.storage_path then website_font_faces.asset_id else gen_random_uuid() end,
    storage_path=excluded.storage_path,mime_type=excluded.mime_type,byte_size=excluded.byte_size,sha256=excluded.sha256;
  return jsonb_build_object('font_families',private.website_font_admin_catalog());
end;
$function$
